"texto": "<p><img class=\"formula\" src=\"provas/img/2025/c3-043.png\" alt=\"fórmula (ver prova original)\" style=\"height:1.00em\"><br><img class=\"formula\" src=\"provas/img/2025/c3-044.png\" alt=\"fórmula (ver prova original)\" style=\"height:1.18em\"><br>.</p>\n<p><img class=\"formula\" src=\"provas/img/2025/c3-045.png\" alt=\"fórmula (ver prova original)\" style=\"height:1.00em\"></p>",
